    C c;
    constructor(C _c) { c = _c; }

    // We will call buyCreditMarket to transfer borrow aTokens from this contract to others.
    // Parameters: borrower (address used by buyCreditMarket when creating new credit), amount (cash or credit depending on exactAmountIn), tenor, creditPositionId, deadline, minAPR, exactAmountIn flag, and an ether value to send if needed.
    function run(address borrower, uint256 amount, uint256 tenor, uint256 creditPositionId, uint256 deadline, uint256 minAPR, bool exactAmountIn, uint256 etherValue) public payable {
        require(address(this).balance >= etherValue, "insufficient test balance");

        // Observe variable pool liquidity before
        // We can only observe via SizeView.data().variablePool which returns IPool address
        (uint256 beforeDebtCount, uint256 beforeCreditCount) = c.getPositionsCount(); // just to make a read
        address variablePoolAdr = c.data().variablePool;
        // read underlying borrow token balance of variablePool via public view: use IERC20 balanceOf through external call to token; but we cannot call non-existent functions here. Instead, we observe borrowAToken.totalSupply() before and after as a proxy for liquidity movement.
        uint256 borrowATokenSupplyBefore = c.data().borrowAToken.totalSupply();

        // Prepare params struct for buyCreditMarket
        // Build calldata by calling c.buyCreditMarket with struct. Solidity allows direct call.
        // Try the call and capture revert
        bool reverted;
        bytes memory ret;
        try c.buyCreditMarket{value: etherValue}(BuyCreditMarketParams({
            borrower: borrower,
            creditPositionId: creditPositionId,
            amount: amount,
            tenor: tenor,
            deadline: deadline,
            minAPR: minAPR,
            exactAmountIn: exactAmountIn
        })) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 borrowATokenSupplyAfter = c.data().borrowAToken.totalSupply();

        // General rule: if call reverted then scaled supply unchanged; otherwise supplyAfter <= supplyBefore + amount
        // We cannot reason exact about internal conversions, but a safe general invariant: the borrowAToken totalSupply does not increase by more than amount when caller used exactAmountIn=true; and if reverted it's equal.
        if (exactAmountIn) {
            if (reverted) {
                assert(borrowATokenSupplyAfter == borrowATokenSupplyBefore);
            } else {
                // supply may increase up to amount (in underlying units scaled to aToken accounting), so enforce upper bound
                assert(borrowATokenSupplyAfter <= borrowATokenSupplyBefore + amount);
            }
        } else {
            // If not exactAmountIn we don't make a tight numeric bound; require only that on revert supply unchanged
            if (reverted) {
                assert(borrowATokenSupplyAfter == borrowATokenSupplyBefore);
            } else {
                // when successful without exactAmountIn, supply should be >= before (we expect supply not to decrease when depositing)
                assert(borrowATokenSupplyAfter >= borrowATokenSupplyBefore);
            }
        }
    }

    // We need to reference the BuyCreditMarketParams struct type from the existing compilation unit.
    receive() external payable {}
