contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test Deposit.executeDeposit for underlying borrow token path by calling c.deposit with token = underlyingBorrowToken.
    // Parameters:
    // - amount: declared deposit amount (in underlying token decimals)
    // - to: recipient address for the minted borrowAToken equivalent
    // - etherValue: Ether forwarded when depositing WETH (we won't use WETH path so require 0)
    function run(uint256 amount, address to, uint256 etherValue) public payable {
        // This test uses only the borrow-token deposit path; disallow sending ETH to avoid WETH handling.
        require(etherValue == 0, "etherValue must be 0");
        // ensure this contract has enough balance if ether were needed
        require(address(this).balance >= etherValue, "insufficient test balance");

        // Read observable before-values via public view functions
        // Get DataView to obtain the borrowAToken contract and underlyingBorrowToken address
        SizeView.DataView memory dv = c.data();
        // borrowAToken has public totalSupply() and balanceOf
        uint256 borrowATokenTotalBefore = dv.borrowAToken.totalSupply();
        uint256 borrowATokenBalanceToBefore = dv.borrowAToken.balanceOf(to);

        // Build DepositParams struct in local memory and call c.deposit.
        // The DepositParams type is defined in the compilation unit; construct calldata by direct call.
        bool reverted;
        try c.deposit{value: etherValue}(DepositParams({ token: address(dv.underlyingBorrowToken), amount: amount, to: to })) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        SizeView.DataView memory dv2 = c.data();
        uint256 borrowATokenTotalAfter = dv2.borrowAToken.totalSupply();
        uint256 borrowATokenBalanceToAfter = dv2.borrowAToken.balanceOf(to);

        // General invariant to assert:
        // - If deposit reverted, total supply and recipient balance unchanged.
        // - If deposit succeeded, total supply did not increase by more than `amount` (in underlying units).
        //   Also the recipient's borrowAToken balance did not increase by more than `amount`.
        // Note: borrowAToken in this system represents unscaled underlying amounts through NonTransferrableScaledToken.balanceOf which returns unscaled amounts.

        if (reverted) {
            assert(borrowATokenTotalAfter == borrowATokenTotalBefore && borrowATokenBalanceToAfter == borrowATokenBalanceToBefore);
        } else {
            // After a successful deposit, the total supply and recipient balance should be >= before and increase no more than `amount`.
            // Use <= to enforce upper bound and >= to ensure non-decrease.
            assert(borrowATokenTotalAfter >= borrowATokenTotalBefore && borrowATokenTotalAfter <= borrowATokenTotalBefore + amount);
            assert(borrowATokenBalanceToAfter >= borrowATokenBalanceToBefore && borrowATokenBalanceToAfter <= borrowATokenBalanceToBefore + amount);
        }
    }

    receive() external payable {}
}

