contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Run a single multicall on C and assert CapsLibrary invariant holds across the multicall
    // Inputs:
    // - calls: an array of bytes representing the calldata to pass to c.multicall
    // - valueSent: Ether to send along with the multicall (if any)
    function run(bytes[] calldata calls, uint256 valueSent) public payable {
        // ensure this contract has enough balance if value is to be forwarded
        if (valueSent > 0) {
            require(address(this).balance >= valueSent, "Insufficient test balance");
        }

        // Observe before-supplies via public getters on c.data().borrowAToken.totalSupply() isn't directly available,
        // but c.data() returns a DataView including borrowAToken (NonTransferrableScaledToken) and debtToken (NonTransferrableToken).
        // We can call c.data() to get the DataView, then query totalSupply() on the tokens via their public functions.

        // Get DataView
        (uint256 beforeDebtCount, uint256 beforeCreditCount) = c.getPositionsCount();
        // get borrow aToken and debt token total supplies via data() view
        ISize.DataView memory dv = c.data();
        uint256 borrowATokenSupplyBefore = dv.borrowAToken.totalSupply();
        uint256 debtTokenSupplyBefore = dv.debtToken.totalSupply();

        bool reverted = false;
        bytes[] memory results;
        // perform multicall, catching reverts
        try c.multicall{value: valueSent}(calls) returns (bytes[] memory r) {
            results = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values (even if multicall reverted, state should be unchanged; observation will reflect that)
        ISize.DataView memory dvAfter = c.data();
        uint256 borrowATokenSupplyAfter = dvAfter.borrowAToken.totalSupply();
        uint256 debtTokenSupplyAfter = dvAfter.debtToken.totalSupply();

        // According to CapsLibrary.validateBorrowATokenIncreaseLteDebtTokenDecrease, if borrowATokenSupplyAfter > borrowATokenSupplyBefore
        // and borrowATokenSupplyAfter > cap, then borrowATokenSupplyIncrease must be <= debtTokenSupplyDecrease.
        // We don't have direct access to the cap, but if the increase > 0 and after > before and after > before implies possibly above cap.
        // To make a general invariant check: whenever borrowATokenSupplyAfter > borrowATokenSupplyBefore,
        // the increase must be <= max(debtTokenSupplyBefore - debtTokenSupplyAfter, type(uint256).max) (i.e., cannot exceed the decrease).

        uint256 borrowIncrease = borrowATokenSupplyAfter >= borrowATokenSupplyBefore
            ? borrowATokenSupplyAfter - borrowATokenSupplyBefore
            : 0;
        uint256 debtDecrease = debtTokenSupplyBefore >= debtTokenSupplyAfter
            ? debtTokenSupplyBefore - debtTokenSupplyAfter
            : 0;

        // If multicall reverted, the net effect must be zero on supply values (state unchanged). Ensure that.
        if (reverted) {
            // then supplies must be equal to before values
            assert(borrowATokenSupplyAfter == borrowATokenSupplyBefore && debtTokenSupplyAfter == debtTokenSupplyBefore);
        } else {
            // If multicall succeeded, enforce the CapsLibrary condition in the general form:
            // borrowIncrease <= debtDecrease OR borrowATokenSupplyAfter <= dvAfter.borrowAToken.totalSupply() /* tautology */
            // We assert the meaningful condition: borrowIncrease <= debtDecrease || borrowATokenSupplyAfter <= c.riskConfig().borrowATokenCap()
            // But c.riskConfig() isn't an exposed function; however c.riskConfig() is exposed via riskConfig() on SizeView.
            ISize.InitializeRiskConfigParams memory rc = c.riskConfig();
            // If after supply is above cap, then borrowIncrease must be <= debtDecrease.
            if (borrowATokenSupplyAfter > rc.borrowATokenCap) {
                assert(borrowIncrease <= debtDecrease);
            } else {
                // If not above cap, no constraint required by the library; assert that supplies are consistent non-negative.
                assert(borrowATokenSupplyAfter >= borrowATokenSupplyBefore || borrowATokenSupplyAfter <= borrowATokenSupplyBefore + borrowIncrease);
            }
        }
    }

    // Allow contract to receive Ether for test funding
    receive() external payable {}
}

