    // Verifies: if multicall reverts then public supplies unchanged; otherwise if borrowAToken.totalSupply() > riskConfig.borrowATokenCap
    // then borrow increase <= debt decrease.
    function run(bytes[] calldata calls, uint256 valueSent) public payable {
        // If forwarding ETH, ensure this contract has funds available
        if (valueSent > 0) {
            require(address(this).balance >= valueSent);
        }

