        uint256 borrowATokenSupplyBefore = dvBefore.borrowAToken.totalSupply();
        uint256 debtTokenSupplyBefore = dvBefore.debtToken.totalSupply();
        uint256 cap = c.riskConfig().borrowATokenCap;

        bool reverted;
        bytes[] memory results;
        // perform multicall and catch reverts
        try c.multicall{value: valueSent}(calls) returns (bytes[] memory r) {
            reverted = false;
            results = r;
        } catch {
            reverted = true;
        }

        // Observe after-values
        ISize.DataView memory dvAfter = c.data();
        uint256 borrowATokenSupplyAfter = dvAfter.borrowAToken.totalSupply();
        uint256 debtTokenSupplyAfter = dvAfter.debtToken.totalSupply();

        // Compute increase / decrease (use non-underflowing comparisons)
        uint256 borrowIncrease = borrowATokenSupplyAfter >= borrowATokenSupplyBefore
            ? borrowATokenSupplyAfter - borrowATokenSupplyBefore
            : 0;
        uint256 debtDecrease = debtTokenSupplyBefore >= debtTokenSupplyAfter
            ? debtTokenSupplyBefore - debtTokenSupplyAfter
            : 0;

        if (reverted) {
            // If multicall reverted, the public token supplies must be unchanged
            assert(borrowATokenSupplyAfter == borrowATokenSupplyBefore && debtTokenSupplyAfter == debtTokenSupplyBefore);
        } else {
            // If multicall succeeded and borrowAToken supply is above cap, the borrow increase must be <= debt decrease
            // Otherwise no strong guarantee from CapsLibrary; still assert non-negative arithmetic relation
            if (borrowATokenSupplyAfter > cap) {
                assert(borrowIncrease <= debtDecrease);
            } else {
                // sanity: total supplies are consistent with computed increase/decrease
                // (this avoids a vacuous constant assertion)
                assert(borrowATokenSupplyAfter == borrowATokenSupplyBefore + borrowIncrease);
            }
        }
    }

    receive() external payable {}
}

